import osfrom qgis.PyQt.QtCore import QCoreApplicationfrom qgis.core import QgsProcessingAlgorithm, QgsProcessingParameterRasterLayer, QgsProcessingParameterFileDestinationfrom qgis.core import QgsProcessingParameterFile, QgsProcessingParameterEnumfrom landspy import DEM, Grid, HCurvefrom qgis import processingimport numpy as npclass HypsometricCurves(QgsProcessingAlgorithm):    # Constants used to refer to parameters and outputs They will be    # used when calling the algorithm from another algorithm, or when    # calling from the QGIS console.    INPUT_DEM = 'INPUT_DEM'    BASINS = 'BASINS'    OUT_CURVES = 'OUT_CURVES'    NAMES = "NAMES"    def __init__(self):        super().__init__()    def createInstance(self):        return type(self)()     def name(self):        """        Rerturns the algorithm name, used to identify the algorithm.        Must be unique within each provider and should contain lowercase alphanumeric characters only.        """        return "hypsometricCurves"         def displayName(self):        """        Returns the translated algorithm name, which should be used for any        user-visible display of the algorithm name.        """        return self.tr("Get Hypsometric Curves")        def groupId(self):        """        Returns the unique ID of the group this algorithm belongs to.        """        return "geomorphic_indexes"    def group(self):        """        Returns the name of the group this algorithm belongs to.        """        return self.tr("Geomorphic Indexes")    def shortHelpString(self):        """        Returns a localised short helper string for the algorithm.         """        texto = """                    Calculates a hypsometric curve for each basin in the input raster.                    DEM: Input Digital Elevation Model.                    Basins: Raster containing the drainage basin IDs.                    Basin Names [Optional]: Text file with one id;name pair per line. Basins without a name use their ID as the name.                    Output Hypsometric Curves: NumPy file (*.npy) with the calculated curves.                    """        return texto     def tr(self, string):        return QCoreApplication.translate('Processing', string)    def helpUrl(self):        return "https://github.com/geolovic/qgs_landspy"    def initAlgorithm(self, config=None):        """        Here we define the inputs and output of the algorithm, along        with some other properties.        """        self.addParameter(QgsProcessingParameterRasterLayer(self.INPUT_DEM,  self.tr("DEM")))        self.addParameter(QgsProcessingParameterRasterLayer(self.BASINS, self.tr("Basins")))        self.addParameter(QgsProcessingParameterFileDestination(self.OUT_CURVES, self.tr("Hypsometric Curves"), fileFilter="Numpy file (*.npy)"))        self.addParameter(QgsProcessingParameterFile(self.NAMES, self.tr("Basin Names"), defaultValue="", optional=True))     def processAlgorithm(self, parameters, context, feedback):        """        Here is where the processing itself takes place.        """        input_dem = self.parameterAsRasterLayer(parameters, self.INPUT_DEM, context)        input_basins = self.parameterAsRasterLayer(parameters, self.BASINS, context)        names_file = self.parameterAsString(parameters, self.NAMES, context)        out_curves = self.parameterAsFileOutput(parameters, self.OUT_CURVES, context)        dem = DEM(input_dem.source())        basins = Grid(input_basins.source())        nodata = basins.getNodata()        bids = np.unique(basins.readArray())        if nodata is not None:            bids = bids[~np.isnan(bids)] if np.isnan(nodata) else bids[bids != nodata]        names = {}        if names_file:            try:                with open(names_file) as infile:                    for linea in infile:                        basin_id, name = linea.rstrip("\r\n").split(";", 1)                        names[int(basin_id)] = name.strip()            except (OSError, ValueError):                feedback.setProgressText("Wrong names file!!, using ids as names...")                names = {}        curves = []        for bid in bids:            curva = HCurve(dem, basins, bid=bid, name=names.get(bid) or str(bid))            curves.append(curva)        curves = np.array(curves)        out_curves = os.path.splitext(out_curves)[0] + ".npy"        np.save(out_curves, curves, allow_pickle=True)        return {self.OUT_CURVES: out_curves}